import {nhplConfig as config} from './nhpl-config.js';
import {createNhplData} from './nhpl-data.js';
import {createScene} from './nhpl-scene.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('pt-BR',{maximumFractionDigits:1}):'Indisponível';
const time=v=>v?new Date(v).toLocaleString('pt-BR'):'Nenhuma leitura';
const duration=v=>typeof v==='number'?`${Math.floor(v/60)}min ${Math.floor(v%60)}s`:'Indisponível';
const btn=(text,action,extra='')=>`<button type="button" data-nhpl="${action}" ${extra}>${text}</button>`;
const data=createNhplData();let current=null;
function open({machine,read,manualState,trigger}) {
  if(current)return;
  const dialog=document.createElement('dialog');dialog.className='nhpl-dialog';dialog.setAttribute('aria-labelledby','nhpl-title');
  dialog.innerHTML=`<header><div><h2 id="nhpl-title">${esc(config.title)}</h2><span class="nhpl-badge">${esc(config.disclaimer)}</span></div><div class="nhpl-toolbar">${btn('Modo TV','tv','aria-pressed="false"')}${btn('Tela cheia','fullscreen')}${btn('×','close','aria-label="Fechar supervisório NHPL" autofocus')}</div></header>
    <div class="nhpl-meta"><p data-meta></p><p class="nhpl-source" data-source role="status"></p><p data-unit></p><details ${innerWidth>850?'open':''}><summary>Modelos e variantes de apresentação</summary><div class="nhpl-toolbar"><label>Modelo visual <select data-model>${Object.keys(config.models).map(m=>`<option>${m}</option>`).join('')}</select></label><label>Variante visual <select data-variant>${config.variants.map(m=>`<option ${m==='Medium'?'selected':''}>${m}</option>`).join('')}</select></label></div><small>${esc(config.variantAssociation)} Seleção visual não altera receita.</small></details></div>
    <div class="nhpl-kpis">${['Aprovados / meta do turno','Hora / meta da hora','Estado da máquina','Tempo de parada','Refugos','Alertas ativos'].map((label,i)=>`<div class="nhpl-kpi"><span>${label}</span><strong data-kpi="${i}"></strong></div>`).join('')}</div>
    <div class="nhpl-main"><section class="nhpl-view" aria-label="Visualização 3D"><div class="nhpl-canvas"></div><p class="nhpl-caption" data-motion></p><div class="nhpl-toolbar">${btn('Restaurar visão','reset')}${btn('Girar','rotate')}${btn('Aproximar','zoom-in')}${btn('Afastar','zoom-out')}<label><input type="checkbox" data-route checked> Percurso</label></div><p class="nhpl-caption">Arraste para girar · roda/pinça para aproximar · botão direito ou dois dedos para deslocar.</p><div class="nhpl-stations">${config.stations.map((s,i)=>btn(`${i+1} · ${esc(s.name)}`,'station',`data-station="${s.id}" aria-pressed="false"`)).join('')}</div></section>
    <details class="nhpl-panel" ${innerWidth>850?'open':''}><summary>Detalhes da estação</summary><div data-detail></div><div data-alerts aria-live="polite"></div><label><input type="checkbox" data-sound> Som opcional dos alertas</label><p><small>Alertas locais. Nenhum e-mail ou mensagem será enviado.</small></p></details></div>
    <div class="nhpl-history"><details><summary>Histórico, paradas e motivos</summary><div data-history></div></details><details><summary>Produção hora a hora</summary><p>Simulação: diferenças do contador desde a abertura da sessão, sem reconstruir horas anteriores. Registros: agrupados pela hora de conclusão do apontamento, sem rastreamento individual.</p><div data-hourly></div></details><details><summary>OEE, MTBF, MTTR e regras propostas</summary><p data-metrics></p><p>Proposta desativada, sujeita à validação: aprovados da hora / meta da hora. Faixas exclusivas: &lt;60% gerência; 60–&lt;80% supervisão; 80–&lt;95% líderes. Período: hora civil completa. Sem disparos externos. Configuração em nhpl-config.js.</p><p data-goal></p></details></div>
    <div class="nhpl-demo"><strong>Controles da demonstração — somente memória</strong><div class="nhpl-toolbar">${btn('Operar / retomar','operando')}${btn('Parada em montagem B','parada')}${btn('Setup','setup')}${btn('Manutenção','manutencao')}${btn('Perder comunicação','sem-leitura')}${btn('Pausar demonstração','pause','aria-pressed="false"')}</div><p class="nhpl-caption">Montagem, parâmetros e transporte ilustrativos; não são instruções para operar a NHPL.</p></div>`;
  document.body.append(dialog);dialog.showModal();let scene=null,sample=null,station='montagem-b',model='VGARD HP',sound=null,previousAlarms=0,closed=false;
  function select(id){station=id;scene?.select(id);updateDetail();dialog.querySelectorAll('[data-station]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.station===id));}
  function updateDetail(){if(!sample)return;const s=config.stations.find(s=>s.id===station),actual=sample.stationStates?.[station];const simulated=sample.source==='simulated';
    dialog.querySelector('[data-detail]').innerHTML=`<h3>${esc(s.name)}</h3><p>${esc(s.activity)}</p><p>Estado: ${esc(simulated?(sample.stateLabel==='Parada'&&station==='montagem-b'?'Parada demonstrativa':sample.stateLabel):(actual?.state||'Indisponível — sem sinal de estação'))}</p><p>Início: ${time(actual?.stateSince||(simulated?sample.stateSince:null))}</p><h3>Parâmetros ${simulated?'simulados':''}</h3>${Object.values(actual?.parameters||sample.parameters||{}).map(p=>`<p>${esc(p.nome)}: ${number(p.value)} ${esc(p.unidade)} ${actual?'':'(máquina global)'}</p>`).join('')||'<p>Indisponível</p>'}`;
  }
  function update(){
    if(closed)return;sample=data.read(read(),MSA.telemetry.mode,manualState());sample.paused=MSA.telemetry.paused;
    const simulated=sample.source==='simulated';const goal=sample.goalRecord;
    dialog.querySelector('[data-kpi="0"]').previousElementSibling.textContent=MSA.telemetry.mode==='records'?'Aprovados hoje / meta do período':'Aprovados / meta do turno';
    dialog.querySelector('[data-meta]').textContent=`Produto: ${simulated?model:sample.model||'Indisponível'} · Variante: ${simulated?dialog.querySelector('[data-variant]').value:sample.variant||'Indisponível'} · Ordem: ${sample.order||'Indisponível'} · Lote: ${sample.batch||'Indisponível'} · ${sample.shift||'Turno indisponível'}`;
    dialog.querySelector('[data-source]').textContent=`${sample.sourceLabel} · Última atualização: ${time(sample.updatedAt)}`;
    dialog.querySelector('[data-unit]').textContent=`Contagem: ${sample.unit} · Período: ${sample.periodLabel||'Indisponível'}`;
    const values=[`${number(sample.goodCount)} / ${number(goal?.shiftTarget)}`,`${number(sample.hourCount)} / ${number(goal?.hourTarget)}`,sample.stateLabel,duration(sample.stopSeconds),number(sample.rejectedCount),number(sample.alarms.length)];values.forEach((v,i)=>dialog.querySelector(`[data-kpi="${i}"]`).textContent=v);
    dialog.querySelector('[data-motion]').textContent=simulated?'Movimento simulado · transferências e estágios conceituais':sample.stateLabel==='Sem leitura'?'Sem leitura · última atualização preservada · movimento suspenso':'Exemplares estáticos de montagem — não representam localização de peças. Rastreamento exige identificação e eventos de passagem.';
    dialog.querySelector('[data-alerts]').innerHTML=sample.alarms.map(a=>`<p class="nhpl-alert">${esc(a.code)} · ${esc(a.description)}</p>`).join('')||'<p>Sem alertas ativos</p>';
    if(dialog.querySelector('[data-sound]').checked&&sample.alarms.length>previousAlarms&&sound?.state==='running'){const o=sound.createOscillator(),g=sound.createGain();o.connect(g);g.connect(sound.destination);g.gain.value=.04;o.frequency.value=700;o.start();o.stop(sound.currentTime+.18);}previousAlarms=sample.alarms.length;
    dialog.querySelector('[data-history]').innerHTML=`<table><thead><tr><th>Data/hora</th><th>Evento / motivo</th><th>Duração</th></tr></thead><tbody>${(sample.timeline||[]).slice(-12).reverse().map(e=>`<tr><td>${time(e.start)}</td><td>${esc(e.state)} · ${esc(e.reason)}</td><td>${duration(((e.end||sample.updatedAt)-e.start)/1000)}</td></tr>`).join('')||(sample.events||[]).slice(-12).reverse().map(e=>`<tr><td>${time(e.time)}</td><td>${esc(e.description)}</td><td>—</td></tr>`).join('')||'<tr><td colspan="3">Histórico indisponível</td></tr>'}</tbody></table>`;
    dialog.querySelector('[data-hourly]').innerHTML=`<table><thead><tr><th>Hora / período</th><th>Aprovados</th><th>Meta vigente</th></tr></thead><tbody>${sample.hourly.map(h=>`<tr><td>${time(h.time)} ${h.partial?'· parcial':''}</td><td>${number(h.goodCount)}</td><td>${number(goal?.hourTarget)}</td></tr>`).join('')||'<tr><td colspan="3">Indisponível</td></tr>'}</tbody></table>`;
    dialog.querySelector('[data-metrics]').textContent=`OEE: ${number(sample.efficiency?.oee)}${sample.efficiency?'%':''} · MTBF: ${duration(sample.reliability.mtbf)} · MTTR: ${duration(sample.reliability.mttr)}. MTBF/MTTR exigem histórico completo e identificação de falhas.`;
    dialog.querySelector('[data-goal]').textContent=goal?`Meta ${goal.id}: vigente de ${goal.validFrom} até ${goal.validTo} (exclusive), turno ${goal.shift}, ordem ${goal.order}.`:'Meta indisponível: fornecer goalHistory com vigência, turno, ordem e fonte. A meta diária genérica não é usada como meta histórica.';
    dialog.querySelector('.nhpl-demo').hidden=!simulated;dialog.querySelector('[data-nhpl="pause"]').setAttribute('aria-pressed',sample.paused);dialog.querySelector('[data-nhpl="pause"]').textContent=sample.paused?'Retomar demonstração':'Pausar demonstração';
    scene?.update(sample,model);updateDetail();
  }
  try {scene=createScene(dialog.querySelector('.nhpl-canvas'),select);}catch(e){dialog.querySelector('.nhpl-canvas').textContent='Não foi possível iniciar WebGL. Abra em um navegador com aceleração gráfica. Indicadores e estações continuam disponíveis.';console.warn(e);}
  dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-nhpl]');if(!b)return;const a=b.dataset.nhpl;
    if(a==='close')dialog.close();else if(a==='station')select(b.dataset.station);else if(a==='reset')scene?.reset();else if(['rotate','zoom-in','zoom-out'].includes(a))scene?.camera(a);else if(a==='tv'){dialog.classList.toggle('is-tv');b.setAttribute('aria-pressed',dialog.classList.contains('is-tv'));dialog.querySelector('.nhpl-panel').open=true;scene?.reset();}
    else if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await dialog.requestFullscreen();}catch{b.textContent='Tela cheia indisponível';}}
    else if(MSA.telemetry.mode==='simulation'){if(a==='pause')MSA.telemetry.pause();else MSA.telemetry.scenario(machine.id,a);update();}
  });
  dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const nodes=[...dialog.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(n=>!n.disabled&&n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
  dialog.addEventListener('change',e=>{if(e.target.matches('[data-model]')){model=e.target.value;update();}if(e.target.matches('[data-variant]'))update();if(e.target.matches('[data-route]'))scene?.route(e.target.checked);if(e.target.matches('[data-sound]')&&e.target.checked){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){sound||=new Audio();sound.resume();}}});
  const stop=MSA.telemetry.subscribe(update);const timer=setInterval(update,1000);current={dialog,close:()=>dialog.close()};
  dialog.addEventListener('close',()=>{closed=true;stop();clearInterval(timer);scene?.dispose();sound?.close();current=null;dialog.remove();if(trigger?.isConnected)trigger.focus({preventScroll:true});},{once:true});
  select(station);update();
}
window.MSA=window.MSA||{};MSA.nhpl={open,close:()=>current?.close(),get active(){return !!current;}};
